// Handles Telegram voice notes (Whisper transcription) and text messages.
// Sends a typing indicator before handing off to the AI Agent.
const msg = $input.first().json;
const message = msg.message || {};
const chatId = String(message.chat?.id || '');
const text = (message.text || '').trim();
const voice = message.voice || message.audio || null;

if (!chatId) return [];
if (text.startsWith('/')) return [];

const BOT_TOKEN = 'YOUR_BOT_TOKEN';
const OPENAI_KEY = 'YOUR_OPENAI_KEY';

let query = '';

if (voice) {
  // Step 1: Resolve the Telegram file path
  const fileInfo = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.telegram.org/bot${BOT_TOKEN}/getFile`,
    qs: { file_id: voice.file_id },
    timeout: 10000
  });
  const filePath = fileInfo.result?.file_path;
  if (!filePath) throw new Error('Could not resolve voice file path from Telegram');

  // Step 2: Download the OGG audio binary
  const audioData = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.telegram.org/file/bot${BOT_TOKEN}/${filePath}`,
    encoding: null,
    timeout: 30000
  });
  const audioBuffer = Buffer.isBuffer(audioData) ? audioData : Buffer.from(audioData);

  // Step 3: Transcribe with OpenAI Whisper
  const transcription = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.openai.com/v1/audio/transcriptions',
    headers: { 'Authorization': `Bearer ${OPENAI_KEY}` },
    formData: {
      file: {
        value: audioBuffer,
        options: { filename: 'voice.ogg', contentType: 'audio/ogg; codecs=opus' }
      },
      model: 'whisper-1'
    },
    timeout: 60000
  });
  query = transcription.text || '';
} else if (text) {
  query = text;
} else {
  return [];
}

query = query.trim();
if (!query) return [];

// Send typing indicator so user sees the bot is working
await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${BOT_TOKEN}/sendChatAction`,
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ chat_id: chatId, action: 'typing' }),
  timeout: 5000
}).catch(() => {});

return [{ json: { query, chatId } }];

const SERPAPI_KEY = 'YOUR_SERPAPI_KEY';

// Accept input whether n8n passes it as { query: '...' } or { input: '...' }
const inputJson = $input.first().json;
const query = (typeof inputJson.query === 'string' ? inputJson.query : (inputJson.input || Object.values(inputJson)[0] || '')).trim();

if (!query) return [{ json: { result: 'Error: empty query provided.' } }];

const res = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://serpapi.com/search.json',
  qs: { engine: 'google', q: query, num: 10, api_key: SERPAPI_KEY },
  timeout: 15000
});

const results = (res.organic_results || []).slice(0, 8);
if (results.length === 0) return [{ json: { result: 'No results found for: ' + query } }];

const formatted = results.map((r, i) =>
  (i + 1) + '. ' + r.title + '\n   ' + (r.snippet || '') + '\n   URL: ' + r.link
).join('\n\n');

return [{ json: { result: formatted } }];

const SERPAPI_KEY = 'YOUR_SERPAPI_KEY';
const NEWSDATA_KEY = 'YOUR_NEWSDATA_KEY';

const inputJson = $input.first().json;
const query = (typeof inputJson.query === 'string' ? inputJson.query : (inputJson.input || Object.values(inputJson)[0] || '')).trim();

if (!query) return [{ json: { result: 'Error: empty query provided.' } }];

const results = [];

try {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://serpapi.com/search.json',
    qs: { engine: 'google_news', q: query, gl: 'in', hl: 'en', api_key: SERPAPI_KEY },
    timeout: 15000
  });
  for (const r of (res.news_results || []).slice(0, 5)) {
    results.push(r.title + ' — ' + (r.source?.name || 'Google News') + '\n   ' + (r.snippet || '') + '\n   URL: ' + (r.link || ''));
  }
} catch(e) {}

try {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://newsdata.io/api/1/news',
    qs: { country: 'in', language: 'en', q: query, apikey: NEWSDATA_KEY },
    timeout: 15000
  });
  for (const a of (res.results || []).slice(0, 5)) {
    results.push(a.title + ' — ' + (a.source_id || 'NewsData') + '\n   ' + (a.description || '') + '\n   URL: ' + (a.link || ''));
  }
} catch(e) {}

if (results.length === 0) return [{ json: { result: 'No India news found for: ' + query } }];
return [{ json: { result: results.join('\n\n') } }];

const inputJson = $input.first().json;
const input = (typeof inputJson.query === 'string' ? inputJson.query : (inputJson.input || Object.values(inputJson)[0] || '')).trim();

const urls = input.split(',').map(u => u.trim()).filter(u => u.startsWith('http')).slice(0, 3);

if (urls.length === 0) {
  return [{ json: { result: 'Error: no valid URLs provided. Pass comma-separated URLs starting with http. Call web_search first to get relevant URLs.' } }];
}

const texts = [];
for (const url of urls) {
  try {
    const pageText = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://r.jina.ai/' + url,
      headers: { 'Accept': 'text/plain', 'X-Return-Format': 'text' },
      encoding: 'utf8',
      timeout: 20000
    });
    const text = typeof pageText === 'string' ? pageText : String(pageText);
    texts.push('=== SOURCE: ' + url + ' ===\n' + text.slice(0, 4000));
  } catch(e) {
    texts.push('=== SOURCE: ' + url + ' ===\n[Scrape failed: ' + e.message + ']');
  }
}

return [{ json: { result: texts.join('\n\n---\n\n') } }];

// Sends the AI Agent's response back to the user via Telegram.
// Truncates at 4000 chars (Telegram limit is 4096).
const agentOutput = $input.first().json.output || 'No response generated.';
const chatId = $('Get Query').first().json.chatId;
const BOT_TOKEN = 'YOUR_BOT_TOKEN';

let text = agentOutput;
if (text.length > 4000) {
  text = text.slice(0, 3900) + '\n\n<i>[Response truncated — ask me to continue]</i>';
}

await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.telegram.org/bot' + BOT_TOKEN + '/sendMessage',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    chat_id: chatId,
    text: text,
    parse_mode: 'HTML',
    disable_web_page_preview: true
  }),
  timeout: 15000
});

return [{ json: { status: 'sent', chatId } }];
